import{_ as r,V as t,W as n,a0 as s}from"./framework-9a29aaa0.js";const e={},o=s(`<ul><li><a href="#lec18-low-level-network-attacks">lec18 low level network attacks</a><ul><li><a href="#arp-spoofingarp-%E6%AC%BA%E9%AA%97">ARP spoofing(ARP 欺骗)</a></li><li><a href="#dhcp">DHCP</a><ul><li><a href="#1-dhcp-discover%E5%8F%91%E7%8E%B0%E9%98%B6%E6%AE%B5"><strong>1. DHCP Discover（发现阶段）</strong></a></li><li><a href="#2-dhcp-offer%E6%8F%90%E4%BE%9B%E9%98%B6%E6%AE%B5"><strong>2. DHCP Offer（提供阶段）</strong></a></li><li><a href="#3-dhcp-request%E8%AF%B7%E6%B1%82%E9%98%B6%E6%AE%B5"><strong>3. DHCP Request（请求阶段）</strong></a></li><li><a href="#4-dhcp-acknowledgment%E7%A1%AE%E8%AE%A4%E9%98%B6%E6%AE%B5"><strong>4. DHCP Acknowledgment（确认阶段）</strong></a></li><li><a href="#5-ip-%E9%85%8D%E7%BD%AE%E7%94%9F%E6%95%88"><strong>5. IP 配置生效</strong></a></li><li><a href="#6-dhcp-%E7%A7%9F%E7%BA%A6%E7%9A%84%E6%9B%B4%E6%96%B0%E4%B8%8E%E9%87%8A%E6%94%BE"><strong>6. DHCP 租约的更新与释放</strong></a></li><li><a href="#%E6%80%BB%E7%BB%93dhcp-%E8%AF%B7%E6%B1%82%E6%B5%81%E7%A8%8B"><strong>总结：DHCP 请求流程</strong></a></li><li><a href="#%E5%9B%BE%E8%A7%A3dhcp-%E8%AF%B7%E6%B1%82%E6%B5%81%E7%A8%8B"><strong>图解：DHCP 请求流程</strong></a></li><li><a href="#%E5%85%B3%E9%94%AE%E7%82%B9%E6%80%BB%E7%BB%93"><strong>关键点总结</strong></a></li></ul></li><li><a href="#wpa">WPA</a><ul><li><a href="#1-psk-pre-shared-key--%E9%A2%84%E5%85%B1%E4%BA%AB%E5%AF%86%E9%92%A5">1. <strong>PSK (Pre-Shared Key) — 预共享密钥</strong></a><ul><li><a href="#%E7%A4%BA%E4%BE%8B">示例：</a></li></ul></li><li><a href="#2-ptk-pairwise-transient-key--%E9%85%8D%E5%AF%B9%E7%9E%AC%E6%80%81%E5%AF%86%E9%92%A5">2. <strong>PTK (Pairwise Transient Key) — 配对瞬态密钥</strong></a><ul><li><a href="#ptk-%E7%9A%84%E7%94%A8%E9%80%94">PTK 的用途：</a></li></ul></li><li><a href="#3-gtk-group-temporal-key--%E7%BB%84%E4%B8%B4%E6%97%B6%E5%AF%86%E9%92%A5">3. <strong>GTK (Group Temporal Key) — 组临时密钥</strong></a><ul><li><a href="#gtk-%E7%9A%84%E7%94%A8%E9%80%94">GTK 的用途：</a></li></ul></li><li><a href="#pskptk-%E5%92%8C-gtk-%E4%B9%8B%E9%97%B4%E7%9A%84%E5%85%B3%E7%B3%BB"><strong>PSK、PTK 和 GTK 之间的关系：</strong></a></li><li><a href="#%E6%80%BB%E7%BB%93"><strong>总结：</strong></a></li></ul></li></ul></li></ul><h1 id="lec18-low-level-network-attacks" tabindex="-1"><a class="header-anchor" href="#lec18-low-level-network-attacks" aria-hidden="true">#</a> lec18 low level network attacks</h1><h2 id="arp-spoofing-arp-欺骗" tabindex="-1"><a class="header-anchor" href="#arp-spoofing-arp-欺骗" aria-hidden="true">#</a> ARP spoofing(ARP 欺骗)</h2><h2 id="dhcp" tabindex="-1"><a class="header-anchor" href="#dhcp" aria-hidden="true">#</a> DHCP</h2><p><strong>DHCP 请求的流程</strong> 是指一个设备（客户端）如何通过 <strong>DHCP（动态主机配置协议）</strong> 向 <strong>DHCP 服务器</strong> 请求并获取网络配置（如 IP 地址、子网掩码、网关等）的过程。整个流程可以分为以下几个步骤：</p><h3 id="_1-dhcp-discover-发现阶段" tabindex="-1"><a class="header-anchor" href="#_1-dhcp-discover-发现阶段" aria-hidden="true">#</a> <strong>1. DHCP Discover（发现阶段）</strong></h3><p>当 <strong>DHCP 客户端</strong> 启动并连接到网络时，它还没有配置 IP 地址，通常会使用 <strong>0.0.0.0</strong> 作为源地址。此时，客户端会向网络广播一个 <strong>DHCP Discover</strong> 消息，寻找可用的 <strong>DHCP 服务器</strong>。</p><ul><li><strong>消息内容</strong>：DHCP Discover 消息会包含客户端的 MAC 地址（物理地址）以及一些其他信息（如客户端的主机名等），告诉 DHCP 服务器这是一个新的客户端设备，想要获取 IP 配置。</li><li><strong>广播方式</strong>：由于客户端没有 IP 地址，它会发送一个 <strong>广播消息</strong>（目标地址：255.255.255.255），因为它不知道哪个 DHCP 服务器可用。</li></ul><h3 id="_2-dhcp-offer-提供阶段" tabindex="-1"><a class="header-anchor" href="#_2-dhcp-offer-提供阶段" aria-hidden="true">#</a> <strong>2. DHCP Offer（提供阶段）</strong></h3><p>当 <strong>DHCP 服务器</strong> 接收到 DHCP Discover 消息后，它会回复一个 <strong>DHCP Offer</strong> 消息。这个消息会包含以下信息：</p><ul><li><strong>IP 地址</strong>：为客户端分配的 <strong>IP 地址</strong>。</li><li><strong>子网掩码</strong>：适用于客户端的子网掩码。</li><li><strong>默认网关</strong>：客户端的默认网关地址（如果需要）。</li><li><strong>租约时间</strong>：此 IP 地址租用的时间（租约期）。</li><li><strong>其他配置</strong>：例如 DNS 服务器地址、NTP 服务器等。</li></ul><p><strong>DHCP Offer</strong> 是由所有收到 <strong>DHCP Discover</strong> 消息的 DHCP 服务器发出的，因此网络中可能会有多个 DHCP Offer 消息。</p><h3 id="_3-dhcp-request-请求阶段" tabindex="-1"><a class="header-anchor" href="#_3-dhcp-request-请求阶段" aria-hidden="true">#</a> <strong>3. DHCP Request（请求阶段）</strong></h3><p>客户端收到一个或多个 <strong>DHCP Offer</strong> 后，会选择其中一个 <strong>DHCP Offer</strong>（通常选择第一个收到的），并向该 DHCP 服务器发送 <strong>DHCP Request</strong> 消息。此消息表示客户端接受该服务器提供的 IP 地址及配置，并请求使用该 IP 地址。</p><ul><li><strong>消息内容</strong>：客户端会在 <strong>DHCP Request</strong> 消息中明确指定它选择的 DHCP 服务器，并附带之前收到的 <strong>DHCP Offer</strong> 中的 IP 地址。</li><li><strong>目标地址</strong>：此时，客户端已经知道所选 DHCP 服务器的 IP 地址，所以它将 <strong>DHCP Request</strong> 消息发送给该服务器，而不是广播。</li></ul><h3 id="_4-dhcp-acknowledgment-确认阶段" tabindex="-1"><a class="header-anchor" href="#_4-dhcp-acknowledgment-确认阶段" aria-hidden="true">#</a> <strong>4. DHCP Acknowledgment（确认阶段）</strong></h3><p>当 <strong>DHCP 服务器</strong> 收到客户端的 <strong>DHCP Request</strong> 消息后，它会向客户端发送一个 <strong>DHCP Acknowledgment</strong>（确认消息）。这个消息包含的内容与 <strong>DHCP Offer</strong> 消息相同，确认客户端的 IP 地址分配有效。</p><ul><li><strong>消息内容</strong>：此时，DHCP 服务器确认给客户端分配的 IP 地址是有效的，且租约期开始计时。</li><li><strong>租约期</strong>：服务器会开始记录这个 IP 地址的租用信息，并根据租约期对该 IP 地址进行管理。</li></ul><h3 id="_5-ip-配置生效" tabindex="-1"><a class="header-anchor" href="#_5-ip-配置生效" aria-hidden="true">#</a> <strong>5. IP 配置生效</strong></h3><p>一旦客户端收到 <strong>DHCP Acknowledgment</strong> 消息，它就可以使用该 IP 地址及其他配置（如网关、DNS 服务器等）开始与网络中的其他设备进行通信。</p><hr><h3 id="_6-dhcp-租约的更新与释放" tabindex="-1"><a class="header-anchor" href="#_6-dhcp-租约的更新与释放" aria-hidden="true">#</a> <strong>6. DHCP 租约的更新与释放</strong></h3><ul><li><strong>更新租约</strong>：在租约期即将到期时，客户端会发送 <strong>DHCP Request</strong> 消息，向 DHCP 服务器请求续期。服务器收到后会发送 <strong>DHCP Acknowledgment</strong> 消息，继续延长租约。</li><li><strong>释放租约</strong>：当客户端不再需要该 IP 地址时（例如，断开网络连接），它会向 DHCP 服务器发送 <strong>DHCP Release</strong> 消息，释放该 IP 地址供其他设备使用。</li></ul><hr><h3 id="总结-dhcp-请求流程" tabindex="-1"><a class="header-anchor" href="#总结-dhcp-请求流程" aria-hidden="true">#</a> <strong>总结：DHCP 请求流程</strong></h3><ol><li><strong>DHCP Discover</strong>：客户端广播请求，寻找 DHCP 服务器。</li><li><strong>DHCP Offer</strong>：DHCP 服务器响应，提供可用的 IP 地址和配置信息。</li><li><strong>DHCP Request</strong>：客户端选择一个 DHCP 服务器的 Offer，发送请求确认。</li><li><strong>DHCP Acknowledgment</strong>：DHCP 服务器确认 IP 地址分配，客户端开始使用该 IP 地址。</li></ol><hr><h3 id="图解-dhcp-请求流程" tabindex="-1"><a class="header-anchor" href="#图解-dhcp-请求流程" aria-hidden="true">#</a> <strong>图解：DHCP 请求流程</strong></h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>客户端           网络              DHCP 服务器
   |             广播（Discover）     |
   |--------------------------------&gt;|
   |             返回（Offer）        |
   |&lt;--------------------------------|
   |             请求（Request）      |
   |--------------------------------&gt;|
   |             确认（Acknowledge）  |
   |&lt;--------------------------------|
   |          配置生效，通信开始       |
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="关键点总结" tabindex="-1"><a class="header-anchor" href="#关键点总结" aria-hidden="true">#</a> <strong>关键点总结</strong></h3><ul><li><strong>DHCP Discover</strong>：客户端广播寻找 DHCP 服务器。</li><li><strong>DHCP Offer</strong>：DHCP 服务器提供 IP 地址。</li><li><strong>DHCP Request</strong>：客户端请求所选的 DHCP 服务器分配的 IP 地址。</li><li><strong>DHCP Acknowledgment</strong>：DHCP 服务器确认并分配 IP 地址。</li></ul><p>这个过程使得设备能够自动获取网络配置，避免了手动设置 IP 地址的麻烦。</p><h2 id="wpa" tabindex="-1"><a class="header-anchor" href="#wpa" aria-hidden="true">#</a> WPA</h2><p>在 <strong>WPA2</strong> （Wi-Fi Protected Access II）协议中，<strong>PSK</strong>、<strong>PTK</strong> 和 <strong>GTK</strong> 是三个关键的密钥概念，它们用于确保无线网络的 <strong>加密</strong> 和 <strong>安全性</strong>。它们各自有不同的作用和生成方式，下面是对这三个密钥的详细解释：</p><h3 id="_1-psk-pre-shared-key-—-预共享密钥" tabindex="-1"><a class="header-anchor" href="#_1-psk-pre-shared-key-—-预共享密钥" aria-hidden="true">#</a> 1. <strong>PSK (Pre-Shared Key) — 预共享密钥</strong></h3><ul><li><strong>定义</strong>：PSK 是一种基于密码的 <strong>共享密钥</strong>，通常用于 WPA2 的 <strong>个人模式（WPA2-Personal）</strong> 中。它是用户和路由器之间事先共享的密钥，也可以理解为一个 <strong>密码</strong>，在 Wi-Fi 连接时，用户设备和路由器需要通过 PSK 进行身份验证。</li><li><strong>作用</strong>：PSK 用于在客户端（设备）和 <strong>接入点（AP）</strong> 之间的身份验证过程中。客户端和 AP 使用相同的 PSK 来相互验证身份。</li><li><strong>生成方式</strong>：通常由用户设置并手动配置，例如在家庭 Wi-Fi 网络中输入的密码。</li><li><strong>重要性</strong>：PSK 直接影响网络的安全性，因为它决定了双方是否可以正确进行加密和解密。如果 PSK 太简单（如短密码或常见密码），就容易被暴力破解，因此应确保 PSK 的复杂性和长度。</li></ul><h4 id="示例" tabindex="-1"><a class="header-anchor" href="#示例" aria-hidden="true">#</a> 示例：</h4><p>如果你在路由器设置中选择 &quot;WPA2-Personal&quot; 并输入一个密码（如 <code>&quot;wifi_password123&quot;</code>），那么这个密码就是 PSK。</p><h3 id="_2-ptk-pairwise-transient-key-—-配对瞬态密钥" tabindex="-1"><a class="header-anchor" href="#_2-ptk-pairwise-transient-key-—-配对瞬态密钥" aria-hidden="true">#</a> 2. <strong>PTK (Pairwise Transient Key) — 配对瞬态密钥</strong></h3><ul><li><p><strong>定义</strong>：PTK 是在 <strong>WPA2</strong> 中由客户端和接入点（AP）通过四次握手过程（4-Way Handshake）动态生成的 <strong>会话密钥</strong>，用于加密后续的客户端与 AP 之间的通信。</p></li><li><p><strong>作用</strong>：PTK 用于保护 <strong>点对点通信</strong> 的数据加密。它是 WPA2 中生成的主要加密密钥，确保数据在客户端与 AP 之间传输时的机密性。</p></li><li><p><strong>生成方式</strong>：PTK 是基于以下几个因素计算出来的：</p><ul><li><strong>PSK</strong>（预共享密钥，通常是用户设置的密码）。</li><li><strong>ANonce</strong>（AP 生成的随机数）。</li><li><strong>SNonce</strong>（客户端生成的随机数）。</li><li><strong>MAC 地址</strong>：客户端和 AP 的物理地址（即 MAC 地址）。</li></ul><p>通过这几个参数，PTK 使用一种密钥派生算法（如 HMAC-SHA1）生成会话密钥，保证每次连接的密钥都是独一无二的。</p></li><li><p><strong>安全性</strong>：PTK 是动态生成的，它不会被公开传输，而是通过握手过程在 AP 和客户端之间私下协商，因此能有效防止密钥被窃取。</p></li></ul><h4 id="ptk-的用途" tabindex="-1"><a class="header-anchor" href="#ptk-的用途" aria-hidden="true">#</a> PTK 的用途：</h4><ul><li><strong>数据加密</strong>：PTK 用于加密数据包（例如，AES 加密），保证数据的机密性。</li><li><strong>数据完整性</strong>：PTK 还可以用于计算消息完整性码（MIC），保证数据在传输过程中没有被篡改。</li></ul><h3 id="_3-gtk-group-temporal-key-—-组临时密钥" tabindex="-1"><a class="header-anchor" href="#_3-gtk-group-temporal-key-—-组临时密钥" aria-hidden="true">#</a> 3. <strong>GTK (Group Temporal Key) — 组临时密钥</strong></h3><ul><li><p><strong>定义</strong>：GTK 是一种用于加密 <strong>广播和组播通信</strong>（例如，发送给所有设备的数据）的密钥。在 <strong>WPA2</strong> 中，GTK 是由接入点（AP）生成并分发给所有连接的客户端的密钥。</p></li><li><p><strong>作用</strong>：GTK 主要用于保护传输到多个设备的数据流（即广播和组播数据）。例如，当 AP 向所有设备发送一个广播消息时，它会使用 GTK 对数据进行加密，然后客户端使用相同的 GTK 来解密。</p></li><li><p><strong>生成方式</strong>：GTK 由接入点生成，并通过四次握手过程的一部分发送给每个连接的客户端。GTK 具有较长的有效期，通常只会在网络发生更改时（如设备加入或离开网络时）重新生成。</p></li><li><p><strong>安全性</strong>：GTK 仅在同一 Wi-Fi 网络中有效。它不会在无线信道上进行明文传输，而是通过 <strong>加密</strong> 进行保护。每当连接状态发生变化时（例如，加入或离开网络），接入点会向客户端广播新的 GTK，确保网络安全。</p></li></ul><h4 id="gtk-的用途" tabindex="-1"><a class="header-anchor" href="#gtk-的用途" aria-hidden="true">#</a> GTK 的用途：</h4><ul><li><strong>加密广播和组播通信</strong>：使用 GTK 对广播数据包（如 ARP 请求、DHCP 请求等）进行加密。</li><li><strong>多设备加密</strong>：GTK 使得多个设备之间可以共享同一个加密密钥，用于加密广播流量，而不需要为每个设备单独生成密钥。</li></ul><h3 id="psk、ptk-和-gtk-之间的关系" tabindex="-1"><a class="header-anchor" href="#psk、ptk-和-gtk-之间的关系" aria-hidden="true">#</a> <strong>PSK、PTK 和 GTK 之间的关系：</strong></h3><ul><li><strong>PSK</strong> 是预共享的密钥，通常由用户设置，它在认证和密钥派生过程中发挥作用。PSK 是 WPA2-Personal 模式下的基础，所有其他密钥的生成都依赖于它。</li><li><strong>PTK</strong> 是由客户端和 AP 在握手过程中协商生成的 <strong>会话密钥</strong>，它用于加密客户端与 AP 之间的通信，确保点对点数据的安全。</li><li><strong>GTK</strong> 是由接入点生成并分发的 <strong>组密钥</strong>，用于加密广播和组播流量，使得同一网络上的多个设备可以共享同一个密钥来保护组数据。</li></ul><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> <strong>总结：</strong></h3><table><thead><tr><th>密钥类型</th><th>描述</th><th>作用</th></tr></thead><tbody><tr><td><strong>PSK</strong></td><td>预共享密钥，通常是用户设置的密码，用于认证</td><td>用于身份验证和密钥派生过程，确保 AP 和客户端之间的安全连接</td></tr><tr><td><strong>PTK</strong></td><td>配对瞬态密钥，动态生成的会话密钥</td><td>用于加密客户端与 AP 之间的点对点数据传输</td></tr><tr><td><strong>GTK</strong></td><td>组临时密钥，由 AP 分发给客户端，用于加密广播数据</td><td>用于加密广播和组播流量，确保同一网络中的多个设备共享密钥</td></tr></tbody></table><p>这三个密钥是 <strong>WPA2</strong> 无线安全协议的核心部分，确保了 <strong>无线通信的机密性</strong> 和 <strong>完整性</strong>。</p>`,52),i=[o];function a(g,l){return t(),n("div",null,i)}const h=r(e,[["render",a],["__file","lec18-low-level-attack.html.vue"]]);export{h as default};
